#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/career-navigator-23819-23868/AWSInfrastructureServices"
cd "$WORKSPACE"
mkdir -p src/__tests__
cat > src/__tests__/smoke.test.js <<'JST'
const React = require('react');
const renderer = require('react-test-renderer');
const AppModule = require('../App');
const App = AppModule && (AppModule.default || AppModule);
test('App renders', () => { const tree = renderer.create(React.createElement(App)).toJSON(); expect(tree).toBeDefined(); });
JST
# ensure react-test-renderer installed
if ! npm --silent --prefix "$WORKSPACE" list react-test-renderer --depth=0 >/dev/null 2>&1; then
  npm i --no-audit --no-fund --silent --prefix "$WORKSPACE" react-test-renderer --save-dev --save-exact
fi
# run tests once (non-watch)
npm test --silent --prefix "$WORKSPACE"
exit 0

